// Provider Meta message ID semantics cannot be assumed from matching a wamid prefix.
const raw=$input.all().map(x=>x.json).filter(x=>x&&Object.keys(x).length);
if(raw.some(x=>x.error))return [{json:{mode:'READ_ONLY',result:'BLOCKED',
 reason:'CHATWOOT_ENTERPRISE_RECIPIENT_TABLE_OR_SELECT_PERMISSION_UNAVAILABLE',crmEventWriteAuthorized:false}}];
if(raw.length>200)throw Error('EVIDENCE_QUERY_LIMIT_REACHED_REFINE_TIME_WINDOW');
const out=raw.map(r=>{
 const statuses={queued:Number(r.queued)||0,skipped:Number(r.skipped)||0,
  sent:Number(r.sent)||0,delivered:Number(r.delivered)||0,read:Number(r.read)||0,failed:Number(r.failed)||0};
 const n=Number(r.audience)||0;
 if(Object.values(statuses).reduce((a,b)=>a+b,0)!==n)throw Error('CHATWOOT_STATUS_TOTAL_MISMATCH');
 return {accountId:r.account_id,campaignDisplayId:r.campaign_display_id,audience:n,
  counts:statuses,candidateWamidCount:Number(r.candidate_wamid_count)||0,
  marketingOptOutFailures:Number(r.marketing_optout_count)||0,lastUpdate:r.last_event_update};
});
return [{json:{checkedAt:new Date().toISOString(),mode:'READ_ONLY',result:out.length?'EVIDENCE_CANDIDATES':'NO_DATA',
 reports:out,providerMessageIdSemanticsVerified:false,crmAttemptMappingVerified:false,
 crmEventWriteAuthorized:false,note:'Database candidate WAMIDs and event timestamps still require exact reconciliation to AGE attempt IDs.'}}];
